effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

   vec3 mod289(vec3 x) {
      return x - floor(x * (1.0 / 289.0)) * 289.0;
    }

    vec2 mod289(vec2 x) {
      return x - floor(x * (1.0 / 289.0)) * 289.0;
    }

    vec3 permute(vec3 x) {
      return mod289(((x*34.0)+1.0)*x);
    }

    float snoise(vec2 v)
      {
      const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                          0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                         -0.577350269189626,  // -1.0 + 2.0 * C.x
                          0.024390243902439); // 1.0 / 41.0
    // First corner
      vec2 i  = floor(v + dot(v, C.yy) );
      vec2 x0 = v -   i + dot(i, C.xx);

      vec2 i1;
      i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
      vec4 x12 = x0.xyxy + C.xxzz;
      x12.xy -= i1;

      i = mod289(i); // Avoid truncation effects in permutation
      vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
    		+ i.x + vec3(0.0, i1.x, 1.0 ));

      vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
      m = m*m ;
      m = m*m ;

      vec3 x = 2.0 * fract(p * C.www) - 1.0;
      vec3 h = abs(x) - 0.5;
      vec3 ox = floor(x + 0.5);
      vec3 a0 = x - ox;

      m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );

      vec3 g;
      g.x  = a0.x  * x0.x  + h.x  * x0.y;
      g.yz = a0.yz * x12.xz + h.yz * x12.yw;
      return 130.0 * dot(m, g);
    }

    float rand(vec2 co)
    {
       return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);
    }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        // if (adaptive) { TanRyu = acScreenNorm; }
        // else { 
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;
        // }

        TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        // TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

        vec4 fragColor;
        vec2 uv = TanRyu;
        float time = progressa * 2.0;

        // Create large, incidental noise waves
        float noise = max(0.0, snoise(vec2(time, uv.y * 0.3)) - 0.3) * (1.0 / 0.7);

        // Offset by smaller, constant noise waves
        noise = noise + (snoise(vec2(time*10.0, uv.y * 2.4)) - 0.5) * 0.15;

        // Apply the noise as x displacement for every line
        float xpos = uv.x - noise * noise * 0.25;
    	fragColor = texture2DCv(black.texture, vec2(xpos, uv.y));

        // Mix in some random interference for lines
        fragColor.rgb = mix(fragColor.rgb, vec3(rand(vec2(uv.y * time))), noise * progressb).rgb;

        // Apply a line pattern every 4 pixels
        if (floor(mod(fragCoord.y * 0.25, 2.0)) == 0.0)
        {
            fragColor.rgb *= 1.0 - (0.15 * noise);
        }

        // Shift green/blue channels (using the red channel)
        fragColor.g = mix(fragColor.r, texture2DCv(black.texture, vec2(xpos + noise * 0.05, uv.y)).g, 0.25);
        fragColor.b = mix(fragColor.r, texture2DCv(black.texture, vec2(xpos - noise * 0.05, uv.y)).b, 0.25);

            const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            vec4 gradmap;
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            gradmap = mix(vec4(0.05,0.05,0.05,1.0),color2,luminance)*fragColor.a;


            vec4 targetLuma = gradmap;
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (lowThreshold*(1.0+1.0))-0.001;
            float lowThresholdA = lowThresholdB-max(1.0, 0.00001);
            float highThresholdA = (1.0*(1.0+1.0)-1.0)+0.001;
            float highThresholdB = highThresholdA+max(1.0, 0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            vec4 fxLuma = targetLuma*lumafx;

    	// gl_FragColor = gradmap * texColor.a;
    	gl_FragColor = (mode? max(texColor, fxLuma) : newLayer(texColor, fxLuma)) * texColor.a;
    	// gl_FragColor = resultfinal;
    }
